import { RspackConfigMutator, RspackConfigTransformer } from '@teambit/rspack.modules.rspack-config-mutator';

/**
 * Adds `builtin:react-refresh-loader` to bit component files in node_modules.
 *
 * This matches what webpack did manually with `@pmmmwh/react-refresh-webpack-plugin/loader`.
 * The base rspack config already applies `react-refresh/babel` via babel-loader to these files
 * (which injects $RefreshReg$/$RefreshSig$ calls), but without this wrapper loader, the modules
 * never call `module.hot.accept()` — so every HMR update is unaccepted and falls back to
 * a full page reload.
 *
 * The RefreshPlugin's auto-injected loader has `exclude: /node_modules/i` by default,
 * which skips all bit components (since they live in node_modules via .bit_roots symlinks).
 * This transformer fills that gap for local bit components only (`_bit_local: true`).
 */
export function createHmrTransformer(): RspackConfigTransformer {
  return (configMutator: RspackConfigMutator) => {
    const config = configMutator.raw;

    if (!config.module) {
      config.module = { rules: [] };
    }
    if (!config.module.rules) {
      config.module.rules = [];
    }

    // unshift so this loader wraps the babel-loader output (runs last in the chain),
    // matching how RefreshPlugin injects its own rule for non-node_modules files.
    config.module.rules.unshift({
      test: /\.(js|mdx?)$/,
      include: /node_modules/,
      descriptionData: {
        _bit_local: (value: unknown) => !!value,
      },
      use: 'builtin:react-refresh-loader',
    });

    return configMutator;
  };
}
